function setTab(id,focus=false){currentTab=id;document.querySelectorAll('[data-tab]').forEach(b=>{const active=b.dataset.tab===id;b.setAttribute('aria-selected',String(active));b.tabIndex=active?0:-1;if(active&&focus)b.focus();});document.querySelectorAll('[role=tabpanel]').forEach(p=>p.hidden=p.id!==`panel-${id}`);if(id==='customers')renderCustomers();if(id==='capital')renderCapital();}
function custom(){activePreset='custom';optimizerMessage='';}
function loadPreset(id){const p=scenario(id);if(!p)return;settings={...structuredClone(p.settings),...household()};activePreset=id==='saved'?'custom':id;optimizerMessage='';renderControls();refresh();}
function switchFund(id){if(!data.funds[id])return;fundStates[settings.fundId]={settings:structuredClone(settings),activePreset,comparatorId,selected:[...selected]};const state=fundStates[id];settings=state?.settings??defaultSettings(data,id);activePreset=state?.activePreset??'central';comparatorId=state?.comparatorId??'central';selected=new Set(state?.selected??['central','plan','pressure','industry']);optimizerMessage='';$('customer-area').value=id==='city'?'city':'westernLehigh';renderDivisionPicker();renderControls();refresh();renderCustomers();}
function download(filename,text,type='application/json'){const blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
